describe('Remember Me Login Feature', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with Remember Me checked and persist session', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Verify login page is visible
    cy.get('[data-testid="login-page"]').should('be.visible');

    // Fill in email and password
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');

    // Verify Remember Me checkbox is visible
    cy.get('[data-testid="remember-me-checkbox"]').should('be.visible');

    // Check Remember Me option
    cy.get('[data-testid="remember-me-checkbox"]').click();

    // Verify checkbox is checked
    cy.get('[data-testid="remember-me-checkbox"]').should('have.value', 'on');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for login API response
    cy.wait('@loginRequest');

    // Verify successful login redirect
    cy.url().should('include', '/dashboard');

    // Verify session cookie is set
    cy.get('[data-testid="session-cookie"]').should('be.present');

    // Verify remember me cookie is set
    cy.get('[data-testid="remember-me-cookie"]').should('be.present');

    // Verify user is logged in
    cy.get('[data-testid="user-name"]').should('contain', 'user@example.com');
  });

  it('should log out and clear session when user clicks logout button', () => {
    // Intercept the logout API call
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');

    // Verify login page is visible
    cy.get('[data-testid="login-page"]').should('be.visible');

    // Fill in email and password
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for login API response
    cy.wait('@loginRequest');

    // Verify successful login redirect
    cy.url().should('include', '/dashboard');

    // Verify session cookie is set
    cy.get('[data-testid="session-cookie"]').should('be.present');

    // Verify remember me cookie is set
    cy.get('[data-testid="remember-me-cookie"]').should('be.present');

    // Verify user is logged in
    cy.get('[data-testid="user-name"]').should('contain', 'user@example.com');

    // Click logout button
    cy.get('[data-testid="logout-button"]').click();

    // Wait for logout API response
    cy.wait('@logoutRequest');

    // Verify logout was successful
    cy.url().should('include', '/login');

    // Verify session cookie is cleared
    cy.get('[data-testid="session-cookie"]').should('not.exist');

    // Verify remember me cookie is cleared
    cy.get('[data-testid="remember-me-cookie"]').should('not.exist');

    // Verify user is logged out
    cy.get('[data-testid="user-name"]').should('not.exist');
  });
});
